        // info relation
        mocked(client.relations).mockResolvedValueOnce({ events: [] });
        setUpChunkEvents([chunk2Event, chunk1Event]);
        infoEvent = mkInfoEvent(VoiceBroadcastInfoState.Resumed);
        playback = await mkPlayback();
    });

    it("durationSeconds should have the length of the known chunks", () => {
        expect(playback.durationSeconds).toEqual(6.5);
    });

    describe("and an event with the same transaction Id occurs", () => {
        beforeEach(() => {
            // @ts-ignore
            playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk2BEvent);
        });

        it("durationSeconds should not change", () => {
            expect(playback.durationSeconds).toEqual(6.5);
        });

        it("should not emit a duplicate length event", () => {
            const onLengthChanged = jest.fn();
            playback.on(VoiceBroadcastPlaybackEvent.LengthChanged, onLengthChanged);
            // @ts-ignore
            playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk2BEvent);
            expect(onLengthChanged).not.toHaveBeenCalled();
        });
    });

    describe("and calling start", () => {
        startPlayback();

        it("should become live while the latest chunk plays", () => {
            expect(playback.getLiveness()).toBe("live");
            expect(onLivenessChanged).toHaveBeenLastCalledWith("live");
        });

        it("should reflect info state changes without duplicate liveness events", () => {
            const emitInfoState = (state: VoiceBroadcastInfoState, timestamp: number): void => {
                const event = mkInfoEvent(state);
                event.event.origin_server_ts = timestamp;
                // @ts-ignore
                playback.infoRelationHelper.emit(RelationsHelperEvent.Add, event);
            };

            onLivenessChanged.mockClear();
            emitInfoState(VoiceBroadcastInfoState.Paused, 1);
            expect(playback.getLiveness()).toBe("grey");
            emitInfoState(VoiceBroadcastInfoState.Paused, 2);
            expect(onLivenessChanged).toHaveBeenCalledTimes(1);
            emitInfoState(VoiceBroadcastInfoState.Resumed, 3);
            expect(playback.getLiveness()).toBe("live");
            emitInfoState(VoiceBroadcastInfoState.Stopped, 4);
            expect(playback.getLiveness()).toBe("not-live");
            expect(onLivenessChanged.mock.calls).toEqual([["grey"], ["live"], ["not-live"]]);
        });

        it("should play the last chunk", () => {
            // assert that the last chunk is played first
            expect(chunk2Playback.play).toHaveBeenCalled();
            expect(chunk1Playback.play).not.toHaveBeenCalled();
        });

        it("stays grey when seeking while paused, then turns live on resume", async () => {
            playback.pause();
            expect(playback.getLiveness()).toBe("grey");

            await playback.skipTo(1);
            expect(chunk1Playback.play).not.toHaveBeenCalled();
            expect(playback.getLiveness()).toBe("grey");

            await playback.resume();
            expect(chunk1Playback.play).toHaveBeenCalled();
            expect(playback.getLiveness()).toBe("live");
        });

        describe("and the playback of the last chunk ended", () => {
            beforeEach(() => {
                chunk2Playback.emit(PlaybackState.Stopped);
            });

            itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Buffering);

            it("should return to grey between chunks", () => {
                expect(playback.getLiveness()).toBe("grey");
                expect(onLivenessChanged).toHaveBeenLastCalledWith("grey");
            });

            describe("and the next chunk arrived", () => {
                beforeEach(() => {
                    // TODO Michael W: Use RelationsHelper
                    // @ts-ignore
                    playback.chunkRelationHelper.emit(RelationsHelperEvent.Add, chunk3Event);
                });

                itShouldSetTheStateTo(VoiceBroadcastPlaybackState.Playing);

                it("should become live again", async () => {
                    await flushPromises();
                    expect(playback.getLiveness()).toBe("live");
                    expect(onLivenessChanged).toHaveBeenLastCalledWith("live");
                });

                it("should play the next chunk", () => {
                    expect(chunk3Playback.play).toHaveBeenCalled();
                });
            });
        });
    });

    it("does not become live if stopped while a chunk is starting", async () => {
        let finishPlaying: () => void;
        mocked(chunk2Playback.play).mockImplementationOnce(() => new Promise<void>(resolve => {
            finishPlaying = resolve;
        }));

        const start = playback.start();
        await flushPromises();
        expect(playback.getLiveness()).toBe("grey");

        playback.stop();
        finishPlaying();
        await start;
        expect(playback.getState()).toBe(VoiceBroadcastPlaybackState.Stopped);
        expect(playback.getLiveness()).toBe("not-live");
    });
});

